const V = Vmax * (0.55 + 0.45 * Math.sin(t * 1.2));
const I = V / Math.max(R, 0.1);
const v = H.plot2d({ xMin: 0, xMax: Math.max(Vmax * 1.05, 1), yMin: 0, yMax: Math.max(Vmax / Math.max(R, 0.1) * 1.05, 0.1), box: { x: 60, y: 50, w: H.W * 0.5 - 40, h: H.H - 120 } });
v.grid(); v.axes();
v.fn(x => x / Math.max(R, 0.1), { color: H.colors.accent, width: 3 });
v.dot(V, I, { r: 6 + Math.sin(t * 4), fill: H.colors.warn });
v.text("operating point", V, I, { color: H.colors.warn, size: 11 });
H.text("x: voltage V (V)   y: current I (A)   slope = 1/R", 60, H.H - 30, { color: H.colors.sub, size: 11 });
const bx = H.W * 0.62, by = 90, w = H.W * 0.3, h = H.H * 0.5;
H.rect(bx, by, w, h, { stroke: H.colors.grid, width: 2, radius: 8 });
H.line(bx, by + h / 2 - 16, bx, by + h / 2 + 16, { color: H.colors.good, width: 4 });
H.line(bx + 8, by + h / 2 - 9, bx + 8, by + h / 2 + 9, { color: H.colors.good, width: 2 });
H.text("V", bx - 18, by + h / 2 + 4, { color: H.colors.good, size: 14, weight: 700 });
const rx0 = bx + w * 0.35, rxw = w * 0.3, ry = by;
let zz = [[rx0, ry]];
for (let k = 0; k <= 6; k++) zz.push([rx0 + (k / 6) * rxw, ry + (k % 2 ? 10 : -10)]);
zz.push([rx0 + rxw, ry]);
H.path(zz, { color: H.colors.accent2, width: 3 });
H.text("R", rx0 + rxw / 2 - 4, ry - 8, { color: H.colors.accent2, size: 13 });
const per = 2 * (w + h);
const dd = ((I / Math.max(Vmax / Math.max(R, 0.1), 0.1)) * 80 + t * 60) % per;
let px, py;
if (dd < w) { px = bx + dd; py = by; }
else if (dd < w + h) { px = bx + w; py = by + (dd - w); }
else if (dd < 2 * w + h) { px = bx + w - (dd - w - h); py = by + h; }
else { px = bx; py = by + h - (dd - 2 * w - h); }
H.circle(px, py, 5, { fill: H.colors.accent });
